// Generado por scripts/construir.mjs — no editar a mano.
const css = "/* ============================================================\n   Sistema de diseño — base Bancolombia\n   Derivado de design-reference/design.md (auditoría del sitio en vivo, 7 ago 2026)\n\n   [CSS]      = extraído con getComputedStyle del sitio real\n   [SVG]      = extraído del SVG decorativo del login\n   [PROPUESTO]= no existe en el sitio, derivado para completar el sistema\n   ============================================================ */\n\n:root {\n\n  /* ---------- Marca ---------- */\n  --bc-amarillo:            #FDDA24; /* [CSS] CTA primario, acentos de marca */\n  --bc-amarillo-svg:        #FDDA23; /* [SVG] misma marca, variante en ilustración */\n  --bc-amarillo-claro:      #FDE773; /* [CSS] fondos suaves, tarjetas promo */\n\n  /* ---------- Neutros ---------- */\n  --bc-negro:               #000000; /* [CSS] h3, botón secundario, nav superior */\n  --bc-carbon:              #2C2A29; /* [CSS] texto principal, header, texto sobre amarillo */\n  --bc-gris-texto:          #808285; /* [CSS] párrafos de cuerpo */\n  --bc-gris-texto-2:        #58595B; /* [CSS] textos auxiliares */\n  --bc-gris-borde:          #D9DADD; /* [CSS] bordes de input, separadores */\n  --bc-gris-deshab:         #CCCCCC; /* [CSS] botón deshabilitado */\n  --bc-gris-deshab-2:       #B3B5B8; /* [CSS] texto deshabilitado */\n  --bc-gris-fondo:          #F4F4F4; /* [CSS] fondo de sección */\n  --bc-gris-fondo-2:        #EEEEEE; /* [CSS] fondo de sección alterno */\n  --bc-gris-fondo-3:        #F2F2F4; /* [CSS] fondo de sección alterno */\n  --bc-gris-pagina:         #F9F9FA; /* [CSS] fondo de página (login) */\n  --bc-blanco:              #FFFFFF;\n\n  /* ---------- Acentos secundarios ---------- */\n  --bc-turquesa:            #66DBB8; /* [CSS] tarjetas promo, categorías FAQ */\n  --bc-lavanda:             #C5ADE5; /* [CSS] tarjetas promo */\n  --bc-melocoton:           #FFB28D; /* [CSS] tarjetas promo */\n  --bc-coral:               #FF7E41; /* [SVG] ilustración, campañas */\n  --bc-purpura:             #9062CD; /* [SVG] ilustración de autenticación */\n\n  /* ---------- Semánticos ----------\n     No se pudieron confirmar en el sitio: los elementos con clase error/alert\n     encontrados eran íconos en gris, no alertas de color.\n     Estos se derivan de la paleta existente. */\n  --bc-exito:               #1F8F6B; /* [PROPUESTO] turquesa oscurecido para contraste AA */\n  --bc-exito-fondo:         #E7F8F2; /* [PROPUESTO] */\n  --bc-alerta:              #B35A1E; /* [PROPUESTO] coral oscurecido */\n  --bc-alerta-fondo:        #FFF1E9; /* [PROPUESTO] */\n  --bc-error:               #C2352B; /* [PROPUESTO] no existe rojo en la marca */\n  --bc-error-fondo:         #FCEDEC; /* [PROPUESTO] */\n  --bc-info:                #5B3E8F; /* [PROPUESTO] púrpura oscurecido */\n  --bc-info-fondo:          #F1EBFA; /* [PROPUESTO] */\n\n  /* ---------- Tipografía ----------\n     Las originales son propietarias y no están disponibles:\n       CIB Sans Bold / CIB Sans Light  → títulos\n       BC Icons                        → iconografía\n     Sustitutos libres, de proporciones cercanas: */\n  /* La pila lleva -apple-system y Segoe UI porque el prototipo se abre en un\n     teléfono, a veces sin conexión: si Google Fonts no carga, cae en la fuente\n     del sistema y no en Times. [AJUSTADO 10 ago 2026] */\n  --bc-font-titulo:  'Manrope', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif; /* sustituto de CIB Sans */\n  --bc-font-cuerpo:  'Open Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;        /* [CSS] la real, es libre */\n\n  --bc-peso-light:    300;  /* CIB Sans Light era 200 */\n  --bc-peso-regular:  400;\n  --bc-peso-semi:     600;\n  --bc-peso-bold:     700;\n\n  /* Escala observada en el sitio [CSS] */\n  --bc-txt-saludo:    36px; /* \"¡Hola!\" del login, en Light */\n  --bc-txt-h1:        32px;\n  --bc-txt-h2:        32px;\n  --bc-txt-h3:        20px;\n  --bc-txt-ui:        16px; /* nav, links, inputs, botones */\n  --bc-txt-cuerpo:    14px;\n  --bc-txt-nota:      12px; /* [PROPUESTO] */\n\n  --bc-alto-linea:      1.5;\n  --bc-alto-linea-tit:  1.2;\n\n  /* ---------- Espaciado ----------\n     [PROPUESTO] — no medido en la auditoría. Escala de 4. */\n  --bc-esp-1:  4px;\n  --bc-esp-2:  8px;\n  --bc-esp-3:  12px;\n  --bc-esp-4:  16px;\n  --bc-esp-5:  24px;\n  --bc-esp-6:  32px;\n  --bc-esp-7:  48px;\n  --bc-esp-8:  64px;\n\n  /* ---------- Radios ---------- */\n  --bc-radio-pill:   999px; /* [CSS] todos los botones del sitio son pill */\n  --bc-radio-card:   12px;  /* [PROPUESTO] */\n  --bc-radio-input:  0px;   /* [CSS] los inputs del login son underline, sin caja */\n  --bc-radio-chip:   999px; /* [CSS] buscador del centro de ayuda */\n\n  /* ---------- Áreas táctiles ----------\n     [PROPUESTO] mínimos de accesibilidad, no del sitio.\n     Relevantes porque 21.7% de personas mayores en Colombia\n     tiene alguna discapacidad certificada (MinSalud). */\n  --bc-tap-min:      44px;\n  --bc-tap-comodo:   56px;\n\n  /* ---------- Bordes ---------- */\n  --bc-borde:        1px solid var(--bc-gris-borde);\n  --bc-borde-fuerte: 2px solid var(--bc-carbon);\n\n  /* ---------- Agregados para el prototipo ----------\n     [PROPUESTO] Todos derivados de la paleta existente. Ninguno inventa un color nuevo:\n     son estados, sombras y superficies que el sitio no expone en CSS.\n     Registrados en prototipo/CHANGELOG.md. */\n\n  --bc-amarillo-presionado: #E9C821; /* [PROPUESTO] amarillo 8% más oscuro, estado :active */\n  --bc-turquesa-oscuro:     #1F8F6B; /* [PROPUESTO] mismo valor que --bc-exito. El turquesa\n                                        #66DBB8 da 1.69:1 contra blanco y no alcanza el 3:1\n                                        que necesita un borde que carga significado */\n\n  /* Superficies */\n  --bc-superficie:      var(--bc-blanco);   /* [PROPUESTO] tarjetas */\n  --bc-superficie-alt:  var(--bc-gris-fondo-2); /* [PROPUESTO] bloque del agente, neutro */\n  --bc-velo:            rgba(44, 42, 41, 0.55); /* [PROPUESTO] fondo de capa modal, carbón 55% */\n\n  /* Sombras — el sitio no las expone; la app sí las usa en la Clave Dinámica */\n  --bc-sombra-1: 0 1px 2px rgba(44, 42, 41, 0.08);            /* [PROPUESTO] */\n  --bc-sombra-2: 0 4px 16px rgba(44, 42, 41, 0.12);           /* [PROPUESTO] tarjeta flotante */\n  --bc-sombra-3: 0 -2px 12px rgba(44, 42, 41, 0.10);          /* [PROPUESTO] barra inferior */\n\n  /* Foco visible — obligatorio para navegación por teclado.\n     Doble anillo: carbón sobre halo blanco, para que se vea también sobre amarillo. */\n  --bc-foco:       var(--bc-carbon);  /* [PROPUESTO] */\n  --bc-foco-halo:  var(--bc-blanco);  /* [PROPUESTO] */\n  --bc-foco-ancho: 3px;               /* [PROPUESTO] */\n\n  /* Duración de las transiciones. Corta a propósito: tiene que correr en teléfonos lentos. */\n  --bc-mov-rapido: 120ms; /* [PROPUESTO] */\n  --bc-mov-medio:  200ms; /* [PROPUESTO] */\n}\n\n/* ============================================================\n   MODO \"LO JUSTO\"\n   Ajustes para el modo simplificado. Misma marca, otra escala.\n   El principio: la marca no cambia, cambia la densidad.\n   ============================================================ */\n\n.lo-justo {\n  /* Tipografía más grande en todo */\n  --bc-txt-h1:      36px;\n  --bc-txt-h2:      28px;\n  --bc-txt-h3:      22px;\n  --bc-txt-ui:      20px;\n  --bc-txt-cuerpo:  18px;  /* mínimo absoluto en este modo */\n  --bc-txt-nota:    18px;  /* [CORREGIDO 10 ago 2026] valía 16px, lo que contradecía la\n                              restricción 2 de PROTOTIPO-SPEC (\"ningún texto por debajo\n                              de 18px\") y la etiqueta de nav de COMPONENTES §11.\n                              Gana la restricción: en este modo no hay letra chica.\n                              Ver prototipo/OBSERVACIONES.md, observación 1. */\n\n  /* Áreas táctiles más generosas */\n  --bc-tap-min:     56px;\n  --bc-tap-comodo:  64px;\n\n  /* Más aire entre elementos */\n  --bc-esp-4:  20px;\n  --bc-esp-5:  32px;\n  --bc-esp-6:  40px;\n\n  /* Contraste reforzado: el texto secundario sube a carbón */\n  --bc-gris-texto: var(--bc-carbon);\n}\n\n/* ============================================================\n   REGLAS DEL MODO LO JUSTO — no son estilos, son restricciones\n   ============================================================\n\n   1. Máximo 3 acciones visibles por pantalla.\n   2. Nada de carruseles, banners promocionales ni contenido que rote.\n   3. Todo botón lleva texto. Ningún ícono solo.\n   4. Un solo botón amarillo por pantalla — el amarillo señala LA acción.\n   5. Ningún texto por debajo de 18px.\n   6. Nada de scroll horizontal.\n   7. Toda pantalla dice dónde estás y cómo volver.\n   8. Las cifras de dinero nunca se abrevian: \"$150.000\", no \"$150K\".\n   9. Ningún estado de error sin causa y siguiente paso.\n  10. Ninguna sesión expira en silencio.\n\n   ============================================================ */\n\n/* ============================================================\n   Base — lo mínimo para que los componentes se comporten igual\n   en cualquier página. No es un reset completo a propósito.\n   ============================================================ */\n\n.lj {\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-cuerpo);\n  line-height: var(--bc-alto-linea);\n  color: var(--bc-carbon);\n  /* El fondo lo pone el propio componente raíz. Sin esto, montado dentro de\n     una página de fondo oscuro —el caso de casi cualquier sandbox— el texto\n     carbón desaparecía. Un sistema que promete 14.28:1 no puede depender de\n     que quien lo use tenga el fondo correcto. */\n  background: var(--bc-blanco);\n  /* Evita que el navegador fuerce controles oscuros sobre superficies claras */\n  color-scheme: light;\n  -webkit-text-size-adjust: 100%;\n}\n\n.lj *,\n.lj *::before,\n.lj *::after { box-sizing: border-box; }\n\n/* Escala en rem: sin esto, subir el texto del sistema al 200% no hace nada.\n   Los px equivalentes van al lado para poder leer la escala de un vistazo. */\n.lj {\n  --bc-txt-h1:     2.25rem;   /* 36px */\n  --bc-txt-h2:     1.75rem;   /* 28px */\n  --bc-txt-h3:     1.375rem;  /* 22px */\n  --bc-txt-ui:     1.25rem;   /* 20px */\n  --bc-txt-cuerpo: 1.125rem;  /* 18px — mínimo absoluto del modo */\n  --bc-txt-nota:   1.125rem;  /* 18px */\n\n  --bc-cifra-1:    2.5rem;    /* 40px */\n  --bc-cifra-2:    2rem;      /* 32px — mínimo para dinero */\n  --bc-cifra-3:    1.375rem;  /* 22px */\n}\n\n/* Foco visible en todo lo interactivo, también sobre amarillo.\n   Doble anillo: carbón sobre halo blanco. */\n.lj :focus-visible {\n  outline: var(--bc-foco-ancho) solid var(--bc-foco);\n  outline-offset: 2px;\n  box-shadow: 0 0 0 calc(var(--bc-foco-ancho) + 2px) var(--bc-foco-halo);\n}\n\n/* Ninguna palabra larga desborda su caja al crecer el texto */\n.lj h1, .lj h2, .lj h3, .lj p, .lj li,\n.lj dd, .lj dt, .lj button, .lj label { overflow-wrap: break-word; }\n\n.lj h1, .lj h2, .lj h3 {\n  font-family: var(--bc-font-titulo);\n  line-height: var(--bc-alto-linea-tit);\n  margin: 0 0 var(--bc-esp-3);\n}\n.lj h1 { font-size: min(var(--bc-txt-h2), 40px); font-weight: var(--bc-peso-bold); }\n.lj h2 { font-size: min(var(--bc-txt-h3), 34px); font-weight: var(--bc-peso-bold); }\n.lj h3 { font-size: var(--bc-txt-ui); font-weight: var(--bc-peso-semi); }\n.lj p  { margin: 0 0 var(--bc-esp-3); }\n\n/* Saludo — el h1 en peso light del login real */\n.lj-saludo {\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-light);\n  font-size: min(var(--bc-txt-h1), 46px);\n  line-height: var(--bc-alto-linea-tit);\n  margin: 0 0 var(--bc-esp-2);\n}\n\n.lj-antetitulo {\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-bold);\n  letter-spacing: .08em;\n  text-transform: uppercase;\n  color: var(--bc-gris-texto-2);\n  margin: 0 0 var(--bc-esp-2);\n}\n\n.lj-nota {\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n  margin: 8px 0 0;\n  line-height: 1.4;\n}\n\n.lj-etiqueta {\n  font-size: var(--bc-txt-cuerpo);\n  color: var(--bc-gris-texto);\n  margin: 0 0 6px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .lj *, .lj *::before, .lj *::after {\n    animation-duration: 1ms !important;\n    transition-duration: 1ms !important;\n  }\n}\n\n/* ============================================================\n   Botones — componentes 1, 2 y 3 de COMPONENTES.md\n\n   Regla: un solo botón amarillo por pantalla. El amarillo señala\n   LA acción, no UNA acción. Y sobre amarillo siempre carbón:\n   blanco sobre #FDDA24 da 1.38:1 y está prohibido.\n   ============================================================ */\n\n.lj-boton {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  width: 100%;\n  min-height: var(--bc-tap-comodo);   /* 56px, crece si crece el texto */\n  padding: 14px var(--bc-esp-5);\n  border: 2px solid transparent;\n  border-radius: var(--bc-radio-pill);\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-ui);\n  font-weight: var(--bc-peso-semi);\n  text-align: center;\n  cursor: pointer;\n  margin: 0 0 10px;\n  transition: background-color var(--bc-mov-rapido) linear;\n}\n\n.lj-boton--primario {\n  background: var(--bc-amarillo);\n  color: var(--bc-carbon);            /* nunca blanco */\n}\n.lj-boton--primario:active { background: var(--bc-amarillo-presionado); }\n\n.lj-boton--secundario {\n  background: transparent;\n  border-color: var(--bc-carbon);\n  color: var(--bc-carbon);\n}\n.lj-boton--secundario:active { background: var(--bc-gris-fondo); }\n\n.lj-boton--texto {\n  background: none;\n  border: 0;\n  text-decoration: underline;\n  color: var(--bc-carbon);\n}\n\n.lj-boton[disabled],\n.lj-boton[aria-disabled=\"true\"] {\n  background: var(--bc-gris-deshab);\n  border-color: transparent;\n  color: var(--bc-gris-deshab-2);\n  cursor: not-allowed;\n}\n\n/* Cargando: el texto se mantiene, nunca se vacía el botón */\n.lj-boton[data-cargando]::after {\n  content: \"\";\n  width: 20px; height: 20px;\n  border: 3px solid currentColor;\n  border-top-color: transparent;\n  border-radius: 50%;\n  animation: lj-girar 700ms linear infinite;\n}\n@keyframes lj-girar { to { transform: rotate(360deg); } }\n\n/* Botón de volver — toda pantalla dice cómo salir */\n.lj-volver {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  min-height: var(--bc-tap-comodo);\n  padding: 0 4px;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-semi);\n  color: var(--bc-carbon);\n}\n\n/* ============================================================\n   Tarjetas — componentes 4 y 5 de COMPONENTES.md\n\n   La tarjeta de acción reemplaza la cuadrícula de íconos de la app\n   actual: una por fila, nunca en cuadrícula, máximo tres por pantalla.\n   ============================================================ */\n\n.lj-tarjeta {\n  background: var(--bc-superficie);\n  border: 1px solid var(--bc-gris-borde);\n  border-radius: var(--bc-radio-card);\n  padding: var(--bc-esp-3) var(--bc-esp-4);\n  margin: 0 0 10px;\n}\n\n/* Destacada: borde amarillo de 2px.\n   Ojo — 1.38:1 contra blanco. Es refuerzo redundante, nunca puede ser\n   lo único que distinga la tarjeta. Siempre acompañar con jerarquía. */\n.lj-tarjeta--destacada { border: 2px solid var(--bc-amarillo); }\n\n/* Tarjeta de saldo: fondo carbón, texto blanco, 14.28:1 */\n.lj-tarjeta--saldo {\n  background: var(--bc-carbon);\n  border-color: var(--bc-carbon);\n  color: var(--bc-blanco);\n  padding: var(--bc-esp-4);\n}\n.lj-tarjeta--saldo .lj-etiqueta,\n.lj-tarjeta--saldo .lj-nota { color: var(--bc-blanco); }\n\n/* ---------- Tarjeta de acción ---------- */\n.lj-accion {\n  display: flex;\n  align-items: center;\n  gap: var(--bc-esp-4);\n  width: 100%;\n  min-height: 72px;\n  padding: var(--bc-esp-4);\n  margin: 0 0 10px;\n  background: var(--bc-superficie);\n  /* El borde identifica un control: necesita 3:1. --bc-gris-borde da\n     1.40:1 y las tarjetas quedaban invisibles con poca visión. */\n  border: 1px solid var(--bc-gris-texto-2);\n  border-radius: var(--bc-radio-card);\n  text-align: left;\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-ui);\n  font-weight: var(--bc-peso-semi);\n  color: var(--bc-carbon);\n  cursor: pointer;\n}\n.lj-accion:active { background: var(--bc-gris-fondo); }\n.lj-accion__icono  { width: 28px; height: 28px; flex: none; }\n.lj-accion__flecha { width: 20px; height: 20px; margin-left: auto; flex: none; }\n\n/* Fila secundaria: para lo que acompaña sin competir */\n.lj-fila {\n  padding: var(--bc-esp-3) 0 var(--bc-esp-4);\n  border-bottom: 1px solid var(--bc-gris-borde);\n  margin: 0 0 var(--bc-esp-4);\n}\n.lj-fila__linea {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--bc-esp-3);\n}\n.lj-fila .lj-etiqueta { margin: 0; }\n.lj-fila .lj-nota { margin: 4px 0 0; }\n\n/* ============================================================\n   Formato de dinero — componente 14\n\n   Formato exacto de la app: \"$ 300.000\". Punto de miles, coma para\n   decimales, espacio después del peso, centavos en tamaño reducido.\n   NUNCA abreviado: \"$150.000\", jamás \"$150K\".\n\n   Mínimo 32px. El techo con min() evita que al 200% se salga de la\n   pantalla: lo que ya era grande no necesita doblar.\n   ============================================================ */\n\n.lj-cifra {\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-1), 52px);\n  line-height: 1.1;\n  letter-spacing: -.02em;\n  margin: 0;\n}\n.lj-cifra--media { font-size: min(var(--bc-cifra-2), 44px); }\n.lj-cifra--chica { font-size: min(var(--bc-cifra-3), 32px); }\n\n/* Centavos a tamaño reducido, como en la app real */\n.lj-cifra__centavos { font-size: .6em; }\n\n/* ---------- Resumen de filas etiqueta/valor ---------- */\n.lj-resumen {\n  border-top: 1px solid var(--bc-gris-borde);\n  margin: 0 0 var(--bc-esp-5);\n}\n.lj-resumen--pegado { margin-bottom: 0; }\n.lj-resumen__fila {\n  display: flex;\n  flex-wrap: wrap;              /* se parte en dos líneas antes que desbordar */\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--bc-esp-4);\n  padding: var(--bc-esp-4) 0;\n  border-bottom: 1px solid var(--bc-gris-borde);\n}\n.lj-resumen__et { color: var(--bc-gris-texto-2); margin: 0; }\n.lj-resumen__va { font-weight: var(--bc-peso-semi); margin: 0; }\n.lj-resumen__va--cifra {\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-2), 42px);\n}\n.lj-resumen__sec {\n  display: block;\n  font-weight: var(--bc-peso-regular);\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n\n/* ---------- Comparar dos cifras ---------- */\n.lj-comparar { margin: 0 0 var(--bc-esp-4); }\n.lj-comparar__fila {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--bc-esp-3);\n  padding: var(--bc-esp-3) 0;\n  border-bottom: 1px solid var(--bc-gris-borde);\n}\n.lj-comparar__fila--tope { border-bottom: 3px solid var(--bc-amarillo); }\n.lj-comparar__fila .lj-etiqueta { margin: 0; }\n\n/* ============================================================\n   El agente — componente 9, el central\n\n   No es una burbuja de chat ni un asistente al que se va a buscar.\n   Es un bloque de ancho completo que aparece dentro del flujo,\n   donde la persona ya está.\n\n   Regla de escritura, no de estilo: el agente habla en pasado, en\n   primera persona, sobre cosas que ya hizo. Si una frase se puede\n   reemplazar por \"¿en qué te puedo ayudar?\", está mal escrita.\n\n   Y nunca envía ni escribe primero. Prepara y espera.\n   ============================================================ */\n\n.lj-agente {\n  display: grid;\n  grid-template-columns: 44px 1fr;\n  gap: var(--bc-esp-3);\n  align-items: start;\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border-radius: var(--bc-radio-card);\n  background: var(--bc-superficie-alt);\n}\n\n/* Anticipa — antes de una acción de riesgo. Fondo neutro. */\n.lj-agente--anticipa { background: var(--bc-superficie-alt); }\n\n/* Explica el fallo — el más importante.\n   Orden obligatorio: qué pasó, de quién fue, qué sigue.\n   Sin rojo: un fallo del banco no es una alarma para la persona. */\n.lj-agente--explica { background: var(--bc-alerta-fondo); }\n\n/* Retoma y confirma */\n.lj-agente--exito { background: var(--bc-exito-fondo); }\n\n.lj-agente__marca {\n  width: 44px;\n  height: 44px;\n  flex: none;\n  border-radius: 50%;\n  background: var(--bc-amarillo);\n  display: grid;\n  place-items: center;\n}\n.lj-agente__marca svg { width: 24px; height: 24px; }\n\n.lj-agente__texto { margin: 0; font-size: var(--bc-txt-cuerpo); }\n.lj-agente__texto + .lj-agente__texto { margin-top: var(--bc-esp-3); }\n.lj-agente__texto strong { font-weight: var(--bc-peso-bold); }\n\n/* ---------- La bitácora ----------\n   Cada cosa que dice el agente termina en una entrada auditable:\n   cuándo lo hizo y si movió plata o no. Es lo que separa un agente\n   de un chatbot — un chatbot no tiene registro de acciones autónomas\n   porque no toma ninguna. */\n.lj-agente__bitacora {\n  display: flex;\n  flex-wrap: wrap;\n  column-gap: 12px;\n  row-gap: 2px;\n  align-items: baseline;\n  margin: var(--bc-esp-3) 0 0;\n  padding-top: 10px;\n  border-top: 1px solid var(--bc-gris-borde);\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n.lj-agente__cuando { font-weight: var(--bc-peso-bold); color: var(--bc-carbon); }\n\n/* ---------- Registro \"Lo que hice por ti\" ---------- */\n.lj-registro { list-style: none; margin: 0; padding: 0; }\n.lj-registro > li {\n  padding: var(--bc-esp-4) 0;\n  border-bottom: 1px solid var(--bc-gris-borde);\n}\n.lj-registro > li:last-child { border-bottom: 0; }\n.lj-registro__hora {\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-bold);\n  color: var(--bc-gris-texto-2);\n  margin: 0 0 6px;\n}\n.lj-registro__que { margin: 0 0 8px; }\n\n.lj-dia {\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-bold);\n  text-transform: uppercase;\n  letter-spacing: .08em;\n  color: var(--bc-gris-texto-2);\n  margin: var(--bc-esp-5) 0 0;\n}\n\n/* Marbete: dice con texto si movió plata. Nunca solo con color. */\n.lj-marbete {\n  display: inline-block;\n  padding: 4px 12px;\n  border: 1px solid var(--bc-gris-borde);\n  border-radius: var(--bc-radio-chip);\n  background: var(--bc-gris-fondo);\n  color: var(--bc-gris-texto-2);\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-semi);\n}\n.lj-marbete--plata { border-color: var(--bc-carbon); color: var(--bc-carbon); }\n\n/* ============================================================\n   El fallo en tres partes\n\n   Ningún error sin causa, responsable y siguiente paso. Siempre en\n   ese orden y siempre con las mismas etiquetas.\n\n   Que sea repetitivo es la gracia: se aprende dónde mirar. El hallazgo\n   que originó todo el sistema es una persona que nunca supo qué había\n   pasado. Un espacio fijo rotulado \"De quién fue\" garantiza que\n   siempre lo encuentre.\n   ============================================================ */\n\n.lj-tres-partes { margin: 0; }\n.lj-tres-partes dt {\n  margin: 0 0 2px;\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-bold);\n  color: var(--bc-gris-texto-2);\n}\n.lj-tres-partes dd {\n  margin: 0 0 var(--bc-esp-3);\n  font-size: var(--bc-txt-cuerpo);\n}\n.lj-tres-partes dd:last-of-type { margin-bottom: 0; }\n\n/* Aviso neutro — para lo que no es un fallo del banco.\n   Sin rojo, sin alarma. \"Ese no es. Te quedan dos intentos.\" */\n.lj-aviso {\n  display: grid;\n  grid-template-columns: 24px 1fr;\n  gap: var(--bc-esp-3);\n  align-items: start;\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border-radius: var(--bc-radio-card);\n  background: var(--bc-gris-fondo-2);\n}\n.lj-aviso--exito { background: var(--bc-exito-fondo); }\n.lj-aviso svg { width: 24px; height: 24px; }\n.lj-aviso p { margin: 0; }\n.lj-aviso p + p { margin-top: 6px; }\n\n/* Salidas — nunca un callejón sin salida */\n.lj-salidas {\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border: 1px solid var(--bc-gris-borde);\n  border-radius: var(--bc-radio-card);\n}\n.lj-salidas__t { font-weight: var(--bc-peso-bold); margin: 0 0 var(--bc-esp-3); }\n.lj-lista-num { margin: 0; padding-left: 22px; }\n.lj-lista-num li { margin: 0 0 var(--bc-esp-3); }\n.lj-lista-num li:last-child { margin-bottom: 0; }\n\n.lj-lista { list-style: none; margin: 0 0 var(--bc-esp-4); padding: 0; }\n.lj-lista li {\n  padding: var(--bc-esp-3) 0 var(--bc-esp-3) var(--bc-esp-4);\n  border-left: 4px solid var(--bc-gris-borde);\n  margin-bottom: 6px;\n}\n\n/* ---------- Certeza sobre el dinero ----------\n   Cuando algo se cae a mitad de una transferencia, lo único que\n   importa es decir con certeza si la plata se movió o no.\n   Nunca \"estamos verificando\". */\n.lj-certeza {\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border: 2px solid var(--bc-carbon);\n  border-radius: var(--bc-radio-card);\n}\n.lj-certeza--no-salio { background: var(--bc-exito-fondo); }\n.lj-certeza--si-salio { background: var(--bc-gris-fondo-2); }\n.lj-certeza__t { font-weight: var(--bc-peso-bold); margin: 0 0 4px; }\n.lj-certeza__cifra {\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-1), 52px);\n  line-height: 1.1;\n  margin: 0 0 6px;\n}\n\n/* ============================================================\n   Campo de entrada — componente 7\n\n   El sitio real usa underline con label flotante. Aquí se cambia a\n   caja con label fijo arriba: el label flotante desaparece al escribir\n   y obliga a recordar qué se estaba llenando.\n\n   La ayuda de formato va ANTES de escribir, no después de fallar.\n   ============================================================ */\n\n.lj-campo { margin: 0 0 var(--bc-esp-4); }\n\n.lj-campo label {\n  display: block;\n  margin: 0 0 6px;\n  font-size: var(--bc-txt-cuerpo);\n  font-weight: var(--bc-peso-semi);\n}\n\n.lj-campo__ayuda {\n  margin: 0 0 8px;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n\n.lj-campo input,\n.lj-campo select,\n.lj-campo textarea {\n  width: 100%;\n  min-height: var(--bc-tap-comodo);\n  padding: 12px var(--bc-esp-3);\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-ui);\n  color: var(--bc-carbon);\n  background: var(--bc-blanco);\n  /* Borde de control: 7.01:1. Con --bc-gris-borde daba 1.40:1. */\n  border: 1px solid var(--bc-gris-texto-2);\n  border-radius: 8px;\n}\n\n.lj-campo--error input { border: 2px solid var(--bc-error); }\n.lj-campo__error {\n  margin: 8px 0 0;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-error);\n}\n\n/* Casilla — el área táctil es la etiqueta entera, no el cuadrito */\n.lj-casilla {\n  display: flex;\n  gap: var(--bc-esp-3);\n  align-items: flex-start;\n  min-height: var(--bc-tap-comodo);\n  padding: var(--bc-esp-3);\n  border: 1px solid var(--bc-gris-texto-2);\n  border-radius: var(--bc-radio-card);\n  cursor: pointer;\n}\n.lj-casilla input {\n  width: 32px;\n  height: 32px;\n  flex: none;\n  margin: 0;\n  accent-color: var(--bc-carbon);\n}\n\n/* ============================================================\n   Comprobante — componente 6\n\n   Sale de una frase textual: alguien va a la sucursal porque\n   \"queda uno más tranquilo de tener como la copia de lo que uno hizo\".\n\n   El borde dentado y el número visible imitan el papel. El puente\n   con lo físico es lo que lo hace funcionar: con ese número te lo\n   imprimen en cualquier sucursal.\n   ============================================================ */\n\n.lj-comprobante {\n  padding: var(--bc-esp-5) var(--bc-esp-4) var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  background: var(--bc-superficie);\n  border: 1px solid var(--bc-gris-borde);\n  border-top: 4px solid var(--bc-amarillo);\n  border-radius: var(--bc-radio-card);\n  box-shadow: var(--bc-sombra-1);\n}\n\n.lj-comprobante__num {\n  margin: 0 0 var(--bc-esp-4);\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-nota);\n  letter-spacing: .06em;\n  color: var(--bc-gris-texto-2);\n}\n\n.lj-comprobante .lj-resumen__fila { padding: 12px 0; }\n\n/* Borde dentado: la metáfora del papel arrancado */\n.lj-dentado {\n  height: 12px;\n  margin: var(--bc-esp-4) calc(var(--bc-esp-4) * -1) 0;\n  background: radial-gradient(circle at 6px 12px,\n              var(--bc-gris-fondo) 6px, transparent 6.5px) repeat-x;\n  background-size: 16px 12px;\n}\n\n/* ============================================================\n   Navegación — componente 11\n\n   La app real marca el destino activo con un bloque amarillo completo\n   detrás del ítem, ocupando todo el alto de la barra. Es una decisión\n   inusual y muy reconocible: se conserva tal cual.\n\n   Cambio: de 5 destinos a 3, todos con ícono Y etiqueta de texto.\n   ============================================================ */\n\n.lj-nav {\n  position: sticky;\n  bottom: 0;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  background: var(--bc-blanco);\n  border-top: 1px solid var(--bc-gris-borde);\n  box-shadow: var(--bc-sombra-3);\n}\n\n.lj-nav button,\n.lj-nav a {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  min-height: 72px;\n  padding: 8px 4px;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  font-family: var(--bc-font-cuerpo);\n  font-size: var(--bc-txt-nota);\n  font-weight: var(--bc-peso-semi);\n  color: var(--bc-gris-texto-2);\n  text-decoration: none;\n  text-align: center;\n}\n.lj-nav svg { width: 24px; height: 24px; }\n\n/* Activo: bloque amarillo completo, texto e ícono en carbón (10.36:1) */\n.lj-nav [aria-current=\"page\"] {\n  background: var(--bc-amarillo);\n  color: var(--bc-carbon);\n}\n\n/* ---------- Encabezado de pantalla ---------- */\n.lj-enc {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--bc-esp-3);\n  padding: var(--bc-esp-4);\n  min-height: 64px;\n}\n.lj-enc--negro { background: var(--bc-carbon); color: var(--bc-blanco); }\n.lj-enc--negro .lj-volver,\n.lj-enc--negro .lj-migaja { color: var(--bc-blanco); }\n\n.lj-migaja {\n  margin: 0;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n\n.lj-marca {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: var(--bc-txt-ui);\n}\n.lj-marca svg { width: 26px; height: 26px; flex: none; }\n\n/* ============================================================\n   Seguridad — sello de identidad (componente 10), palabra y\n   alerta de fraude.\n\n   Sin esto, nada de lo demás sirve: si la persona no puede saber\n   que un mensaje es del banco, la propuesta entera se cae.\n   ============================================================ */\n\n/* Sello de identidad — al pie de cualquier mensaje del agente */\n.lj-sello {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n  margin: 0 0 var(--bc-esp-4);\n  padding: 0 4px;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n  line-height: 1.4;\n}\n.lj-sello svg { width: 18px; height: 18px; flex: none; margin-top: 2px; }\n\n/* ---------- La palabra ----------\n   El estafador ya sabe el nombre de la persona: decir el nombre no\n   prueba nada. Una palabra que solo ella y el banco conocen, sí.\n   Todo mensaje real la trae. */\n.lj-palabra {\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border: 2px solid var(--bc-carbon);\n  border-radius: var(--bc-radio-card);\n  text-align: center;\n}\n.lj-palabra__et {\n  margin: 0 0 6px;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n.lj-palabra__val {\n  margin: 0 0 8px;\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-2), 40px);\n  letter-spacing: .1em;\n}\n\n/* ---------- Alerta de fraude ----------\n   Único sitio donde el amarillo no señala una acción sino un peligro.\n   Amarillo claro con carbón: 11.46:1. Nunca rojo — el rojo se reserva\n   para nada, porque en este sistema no hay rojo. */\n.lj-alerta-fraude {\n  display: grid;\n  grid-template-columns: 26px 1fr;\n  gap: var(--bc-esp-3);\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  background: var(--bc-amarillo-claro);\n  color: var(--bc-carbon);\n  border-radius: var(--bc-radio-card);\n}\n.lj-alerta-fraude svg { width: 26px; height: 26px; }\n.lj-alerta-fraude p { margin: 0; }\n.lj-alerta-fraude p + p { margin-top: 6px; }\n.lj-alerta-fraude .lj-nota { color: var(--bc-carbon); }\n\n/* ---------- Límites de la autonomía ----------\n   Lo hago solo / Siempre te pregunto. La información nunca depende\n   solo del color: cada lista lleva su encabezado. */\n.lj-limites { list-style: none; margin: 0 0 var(--bc-esp-5); padding: 0; }\n.lj-limites li {\n  padding: var(--bc-esp-3) 0 var(--bc-esp-3) var(--bc-esp-4);\n  font-size: var(--bc-txt-cuerpo);\n}\n/* 4.04:1 — el turquesa de marca #66DBB8 daría 1.69:1 y no sirve aquí */\n.lj-limites--solo li     { border-left: 4px solid var(--bc-turquesa-oscuro); }\n.lj-limites--pregunto li { border-left: 4px solid var(--bc-amarillo); }\n\n.lj-titulo-lista {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: var(--bc-esp-3);\n}\n.lj-titulo-lista svg { width: 22px; height: 22px; flex: none; }\n.lj-titulo-lista h2 { margin: 0; }\n\n/* ============================================================\n   Esperas y Clave Dinámica\n\n   Nada de giros infinitos. Toda espera dice qué se está esperando,\n   cuánto lleva, y qué pasa si la persona cierra la app.\n   ============================================================ */\n\n.lj-espera {\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  border: 1px solid var(--bc-gris-borde);\n  border-radius: var(--bc-radio-card);\n}\n.lj-espera__et {\n  margin: 0 0 6px;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n.lj-espera__que {\n  margin: 0 0 8px;\n  font-size: var(--bc-txt-ui);\n  font-weight: var(--bc-peso-semi);\n}\n.lj-espera__num {\n  margin: 0 0 8px;\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-2), 40px);\n  line-height: 1.15;\n}\n\n.lj-barra {\n  height: 8px;\n  margin-top: var(--bc-esp-3);\n  border-radius: var(--bc-radio-pill);\n  background: var(--bc-gris-borde);\n  overflow: hidden;\n}\n.lj-barra > span {\n  display: block;\n  height: 100%;\n  background: var(--bc-carbon);\n}\n\n.lj-contador { text-align: center; margin: 0 0 var(--bc-esp-4); }\n.lj-contador__num {\n  display: block;\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-1), 52px);\n  line-height: 1.1;\n}\n\n/* ---------- Clave Dinámica — componente 12 ----------\n   Es el elemento más distintivo de la app: tarjeta blanca flotante\n   con el código en dígitos grandes agrupados de a tres. Se conserva\n   íntegra. Único cambio: la primera vez, el agente explica qué es. */\n.lj-clave {\n  padding: var(--bc-esp-4);\n  margin: 0 0 var(--bc-esp-4);\n  background: var(--bc-blanco);\n  border: 1px solid var(--bc-gris-borde);\n  border-radius: var(--bc-radio-card);\n  box-shadow: var(--bc-sombra-2);\n  text-align: center;\n}\n.lj-clave__et {\n  margin: 0 0 6px;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n.lj-clave__num {\n  margin: 0 0 8px;\n  font-family: var(--bc-font-titulo);\n  font-weight: var(--bc-peso-bold);\n  font-size: min(var(--bc-cifra-1), 46px);\n  letter-spacing: .12em;\n}\n.lj-clave__tiempo {\n  margin: 0;\n  font-size: var(--bc-txt-nota);\n  color: var(--bc-gris-texto-2);\n}\n.lj-clave__barra {\n  display: block;\n  height: 6px;\n  margin-top: 8px;\n  border-radius: var(--bc-radio-pill);\n  /* Pista oscura: el amarillo sobre --bc-gris-borde daba 1.01:1 y la\n     barra de tiempo era literalmente invisible. Sobre esto da 4.90:1. */\n  background: var(--bc-gris-texto-2);\n  overflow: hidden;\n}\n.lj-clave__barra > span {\n  display: block;\n  height: 100%;\n  background: var(--bc-amarillo);\n}\n\n/* ============================================================\n   Arcos de marca — componente 13\n\n   Trazos curvos gruesos saliendo del borde superior derecho. Es la\n   firma visual de Bancolombia y aparece tanto en el sitio como en la\n   app. Se conservan: son gratis en carga cognitiva porque no son\n   interactivos, y hacen que el modo simple siga siendo reconocible.\n\n   Van en position:absolute a propósito: al ser decorativos, no deben\n   cobrar espacio vertical en un flujo donde cada píxel está peleado.\n   ============================================================ */\n\n.lj-arcos {\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 280px;\n  height: 130px;\n  pointer-events: none;\n}\n\n.lj-pantalla { position: relative; }\n\n@media (max-width: 380px) {\n  .lj-arcos { width: 230px; height: 108px; }\n}\n\n/* ============================================================\n   Teléfono real\n\n   Estos componentes se usan en un celular, no solo en el navegador\n   del escritorio. Nada depende de :hover, que en táctil no existe.\n   Probado a 360, 390 y 430px.\n   ============================================================ */\n\n@media (max-width: 380px) {\n  .lj-cifra                { font-size: min(var(--bc-cifra-1), 36px); }\n  .lj-cifra--media         { font-size: min(var(--bc-cifra-2), 28px); }\n  .lj-certeza__cifra       { font-size: min(var(--bc-cifra-1), 34px); }\n  .lj-clave__num           { font-size: min(var(--bc-cifra-1), 34px); letter-spacing: .08em; }\n  .lj-palabra__val         { font-size: min(var(--bc-cifra-2), 30px); }\n  .lj-contador__num        { font-size: min(var(--bc-cifra-1), 38px); }\n  .lj-resumen__va--cifra   { font-size: min(var(--bc-cifra-2), 28px); }\n}\n\n/* En táctil no hay hover: los estados viven en :active y :focus-visible */\n@media (hover: none) {\n  .lj-accion:active,\n  .lj-boton--primario:active { transition: none; }\n}\n";

let puesto = false;

/** Inyecta el CSS del kit una sola vez. La llaman los componentes solos. */
export function ponerEstilos() {
  if (puesto || typeof document === 'undefined') return;
  puesto = true;
  if (document.getElementById('lo-justo-design-kit')) return;
  const etiqueta = document.createElement('style');
  etiqueta.id = 'lo-justo-design-kit';
  etiqueta.textContent = css;
  document.head.appendChild(etiqueta);
}

export { css };
